                enabled: env_flag("OP_EMQX_EXHOOK_ENABLE"),
                bind_addr: std::env::var("OP_EMQX_EXHOOK_BIND_ADDR")
                    .unwrap_or_else(|_| DEFAULT_EMQX_EXHOOK_BIND_ADDR.to_string()),
                server_cert_path: env_path(
